custom_css:
/* Sandstone: beige main area, sage sidebar, maroon accents */
:root {
  --surface-base: #e8d2b5;
  --surface-gray-1: color-mix(in srgb, #e8d2b5 94%, black);
  --surface-gray-2: color-mix(in srgb, #e8d2b5 89%, black);
  --surface-gray-3: color-mix(in srgb, #e8d2b5 83%, black);
  --surface-elevation-1: color-mix(in srgb, #e8d2b5 35%, white);
  --surface-elevation-2: color-mix(in srgb, #e8d2b5 35%, white);
  --surface-elevation-3: color-mix(in srgb, #e8d2b5 35%, white);
  --outline-gray-1: color-mix(in srgb, #e8d2b5 82%, #590907);
  --outline-gray-2: color-mix(in srgb, #e8d2b5 72%, #590907);
}
/* darker sidebar text so it stays readable on sage */
aside {
  --surface-gray-2: color-mix(in srgb, #a5a79b 85%, black);
  --ink-gray-4: #3f4137;
  --ink-gray-5: #3f4137;
  --ink-gray-6: #2c2d26;
  --outline-gray-1: color-mix(in srgb, #a5a79b 80%, black);
}
/* a touch of maroon: active menu item and links */
aside nav a.font-medium, aside nav a.font-medium span { color: #590907; }
main a:not([class*="bg-"]) { color: #590907; }

/* Apple: gray canvas, white grouped cards, one blue accent. Every token is set for light and dark. */
:root {
  --canvas: #f5f5f7;
  --surface-base: #ffffff;
  --surface-elevation-1: #ffffff;
  --surface-elevation-2: #ffffff;
  --surface-elevation-3: #ffffff;
  --ink-gray-9: #1d1d1f;
  --ink-gray-8: #1d1d1f;
  --ink-gray-7: #424245;
  --ink-gray-6: #6e6e73;
  --ink-gray-5: #6e6e73;
  --ink-gray-4: #86868b;
  --outline-gray-1: #e5e5ea;
  --outline-gray-2: #d2d2d7;
  --accent-tint: color-mix(in srgb, #0071e3 12%, transparent);
  --accent-ink: #0066cc;
}
[data-theme="dark"] {
  --canvas: #000000;
  --surface-base: #1c1c1e;
  --surface-elevation-1: #1c1c1e;
  --surface-elevation-2: #2c2c2e;
  --surface-elevation-3: #3a3a3c;
  --ink-gray-9: #f5f5f7;
  --ink-gray-8: #e5e5ea;
  --ink-gray-7: #c7c7cc;
  --ink-gray-6: #aeaeb2;
  --ink-gray-5: #98989d;
  --ink-gray-4: #8e8e93;
  --outline-gray-1: #2c2c2e;
  --outline-gray-2: #38383a;
  --accent-tint: color-mix(in srgb, #0a84ff 22%, transparent);
  --accent-ink: #2997ff;
}
/* sidebar: a quiet gray column; the selected row is a flat blue tint */
aside { --surface-gray-1: #ececee; --surface-gray-2: #e0e0e3; }
[data-theme="dark"] aside { --surface-gray-1: #161618; --surface-gray-2: #2c2c2e; }
aside .nav-active { box-shadow: none; }
/* links in content use the accent */
main a.underline { color: var(--accent-ink); }

:root {
	--canvas: #ffffff;
	--accent-ink: #1d4ed8;
}
.card,
main > * > .data-table {
	border-color: #dbe4f3;
	box-shadow: 0 1px 3px rgb(30 64 175 / 0.08), 0 1px 2px rgb(30 64 175 / 0.04);
}
main .bar-glass {
	margin: 1rem 1rem 1rem;
	border: 1px solid #dbe4f3;
	border-radius: 1rem;
	box-shadow: 0 1px 3px rgb(30 64 175 / 0.08);
}
main > * > .flex.flex-wrap.items-end.gap-3:not(.bar-glass) {
	margin: 0 1rem 1rem;
	padding: 1rem;
	border: 1px solid #dbe4f3;
	border-radius: 1rem;
	background: #ffffff;
	box-shadow: 0 1px 3px rgb(30 64 175 / 0.08);
}
@media (min-width: 640px) {
	main .bar-glass,
	main > * > .flex.flex-wrap.items-end.gap-3:not(.bar-glass) {
		margin-left: 1.5rem;
		margin-right: 1.5rem;
	}
}

