	--accent-ink: #1d1d1f;
	border-right-color: rgb(0 0 0 / 0.08);
}
aside.w-60 nav a > span:first-child {
	color: #0071e3;
}
aside.w-60 .nav-active {
	box-shadow: none;
	font-weight: 600;
}
aside.w-60 nav .bg-surface-gray-10 {
